/**
 * Drawn line icons, one consistent stroke. Use these instead of emoji or unicode glyphs
 * (✓ × ↗ ↑ ↓ ✏️ 🗑️ …) — those read as auto-generated UI. Icons inherit text color.
 */
type P = { size?: number; className?: string; strokeWidth?: number };

function Svg({ size = 18, className = "", strokeWidth = 1.8, children }: P & { children: React.ReactNode }) {
  return (
    <svg
      viewBox="0 0 24 24"
      width={size}
      height={size}
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
      className={`shrink-0 ${className}`}
    >
      {children}
    </svg>
  );
}

